import{_ as s,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"19 |  Java字节码（基础篇）","description":"","frontmatter":{},"headers":[{"level":2,"title":"操作数栈","slug":"操作数栈","link":"#操作数栈","children":[]},{"level":2,"title":"局部变量区","slug":"局部变量区","link":"#局部变量区","children":[]},{"level":2,"title":"综合示例","slug":"综合示例","link":"#综合示例","children":[]},{"level":2,"title":"Java字节码简介","slug":"java字节码简介","link":"#java字节码简介","children":[]},{"level":2,"title":"总结与实践","slug":"总结与实践","link":"#总结与实践","children":[]}],"relativePath":"深入拆解Java虚拟机/19-Java字节码（基础篇）.md","filePath":"深入拆解Java虚拟机/19-Java字节码（基础篇）.md","lastUpdated":1779821039000}'),i={name:"深入拆解Java虚拟机/19-Java字节码（基础篇）.md"};function t(l,a,o,c,r,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_19-java字节码-基础篇" tabindex="-1">19 | Java字节码（基础篇） <a class="header-anchor" href="#_19-java字节码-基础篇" aria-label="Permalink to &quot;19 |  Java字节码（基础篇）&quot;">​</a></h1><p>在前面的篇章中，有不少同学反馈对Java字节码并不是特别熟悉。那么今天我便来系统性地介绍一遍Java字节码。</p><h2 id="操作数栈" tabindex="-1">操作数栈 <a class="header-anchor" href="#操作数栈" aria-label="Permalink to &quot;操作数栈&quot;">​</a></h2><p>我们知道，Java字节码是Java虚拟机所使用的指令集。因此，它与Java虚拟机基于栈的计算模型是密不可分的。</p><p>在解释执行过程中，每当为Java方法分配栈桢时，Java虚拟机往往需要开辟一块额外的空间作为操作数栈，来存放计算的操作数以及返回结果。</p><p>具体来说便是：执行每一条指令之前，Java虚拟机要求该指令的操作数已被压入操作数栈中。在执行指令时，Java虚拟机会将该指令所需的操作数弹出，并且将指令的结果重新压入栈中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/13720f6eb83d096ec600309648330821.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/13720f6eb83d096ec600309648330821.png" alt=""></a></p><p>以加法指令iadd为例。假设在执行该指令前，栈顶的两个元素分别为int值1和int值2，那么iadd指令将弹出这两个int，并将求得的和int值3压入栈中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/138c20e60c081c8698770ff8d5d93fdb.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/138c20e60c081c8698770ff8d5d93fdb.png" alt=""></a></p><p>由于iadd指令只消耗栈顶的两个元素，因此，对于离栈顶距离为2的元素，即图中的问号，iadd指令并不关心它是否存在，更加不会对其进行修改。</p><p>Java字节码中有好几条指令是直接作用在操作数栈上的。最为常见的便是dup： 复制栈顶元素，以及pop：舍弃栈顶元素。</p><p>dup指令常用于复制new指令所生成的未经初始化的引用。例如在下面这段代码的foo方法中，当执行new指令时，Java虚拟机将指向一块已分配的、未初始化的内存的引用压入操作数栈中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  public void foo() {</span></span>
<span class="line"><span>    Object o = new Object();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // 对应的字节码如下：</span></span>
<span class="line"><span>  public void foo();</span></span>
<span class="line"><span>    0  new java.lang.Object [3]</span></span>
<span class="line"><span>    3  dup</span></span>
<span class="line"><span>    4  invokespecial java.lang.Object() [8]</span></span>
<span class="line"><span>    7  astore_1 [o]</span></span>
<span class="line"><span>    8  return</span></span></code></pre></div><p>接下来，我们需要以这个引用为调用者，调用其构造器，也就是上面字节码中的invokespecial指令。要注意，该指令将消耗操作数栈上的元素，作为它的调用者以及参数（不过Object的构造器不需要参数）。</p><p>因此，我们需要利用dup指令复制一份new指令的结果，并用来调用构造器。当调用返回之后，操作数栈上仍有原本由new指令生成的引用，可用于接下来的操作（即偏移量为7的字节码，下面会介绍到）。</p><p>pop指令则常用于舍弃调用指令的返回结果。例如在下面这段代码的foo方法中，我将调用静态方法bar，但是却不用其返回值。</p><p>由于对应的invokestatic指令仍旧会将返回值压入foo方法的操作数栈中，因此Java虚拟机需要额外执行pop指令，将返回值舍弃。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  public static boolean bar() {</span></span>
<span class="line"><span>    return false;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  public void foo() {</span></span>
<span class="line"><span>    bar();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // foo方法对应的字节码如下：</span></span>
<span class="line"><span>  public void foo();</span></span>
<span class="line"><span>    0  invokestatic FooTest.bar() : boolean [24]</span></span>
<span class="line"><span>    3  pop</span></span>
<span class="line"><span>    4  return</span></span></code></pre></div><p>需要注意的是，上述两条指令只能处理非long或者非double类型的值，这是因为long类型或者double类型的值，需要占据两个栈单元。当遇到这些值时，我们需要同时复制栈顶两个单元的dup2指令，以及弹出栈顶两个单元的pop2指令。</p><p>除此之外，不算常见但也是直接作用于操作数栈的还有swap指令，它将交换栈顶两个元素的值。</p><p>在Java字节码中，有一部分指令可以直接将常量加载到操作数栈上。以int类型为例，Java虚拟机既可以通过iconst指令加载-1至5之间的int值，也可以通过bipush、sipush加载一个字节、两个字节所能代表的int值。</p><p>Java虚拟机还可以通过ldc加载常量池中的常量值，例如ldc #18将加载常量池中的第18项。</p><p>这些常量包括int类型、long类型、float类型、double类型、String类型以及Class类型的常量。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/0cd25310027d1fbcca1d6f3301186199.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/0cd25310027d1fbcca1d6f3301186199.jpg" alt=""></a></p><p><strong>常数加载指令表</strong></p><p>正常情况下，操作数栈的压入弹出都是一条条指令完成的。唯一的例外情况是在抛异常时，Java虚拟机会清除操作数栈上的所有内容，而后将异常实例压入操作数栈上。</p><h2 id="局部变量区" tabindex="-1">局部变量区 <a class="header-anchor" href="#局部变量区" aria-label="Permalink to &quot;局部变量区&quot;">​</a></h2><p>Java方法栈桢的另外一个重要组成部分则是局部变量区，字节码程序可以将计算的结果缓存在局部变量区之中。</p><p>实际上，Java虚拟机将局部变量区当成一个数组，依次存放this指针（仅非静态方法），所传入的参数，以及字节码中的局部变量。</p><p>和操作数栈一样，long类型以及double类型的值将占据两个单元，其余类型仅占据一个单元。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public void foo(long l, float f) {</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    int i = 0;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    String s = &quot;Hello, World&quot;;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>以上面这段代码中的foo方法为例，由于它是一个实例方法，因此局部变量数组的第0个单元存放着this指针。</p><p>第一个参数为long类型，于是数组的1、2两个单元存放着所传入的long类型参数的值。第二个参数则是float类型，于是数组的第3个单元存放着所传入的float类型参数的值。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/228d0f5f2d6437e7aca87c6df2d01bd9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/228d0f5f2d6437e7aca87c6df2d01bd9.png" alt=""></a></p><p>在方法体里的两个代码块中，我分别定义了两个局部变量i和s。由于这两个局部变量的生命周期没有重合之处，因此，Java编译器可以将它们编排至同一单元中。也就是说，局部变量数组的第4个单元将为i或者s。</p><p>存储在局部变量区的值，通常需要加载至操作数栈中，方能进行计算，得到计算结果后再存储至局部变量数组中。这些加载、存储指令是区分类型的。例如，int类型的加载指令为iload，存储指令为istore。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/60615f212fe3c40e152eb1829d5c0073.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/60615f212fe3c40e152eb1829d5c0073.jpg" alt=""></a></p><p><strong>局部变量区访问指令表</strong></p><p>局部变量数组的加载、存储指令都需要指明所加载单元的下标。举例来说，aload 0指的是加载第0个单元所存储的引用，在前面示例中的foo方法里指的便是加载this指针。</p><p>在我印象中，Java字节码中唯一能够直接作用于局部变量区的指令是iinc M N（M为非负整数，N为整数）。该指令指的是将局部变量数组的第M个单元中的int值增加N，常用于for循环中自增量的更新。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  public void foo() {</span></span>
<span class="line"><span>    for (int i = 100; i&gt;=0; i--) {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // 对应的字节码如下：</span></span>
<span class="line"><span>  public void foo();</span></span>
<span class="line"><span>     0  bipush 100</span></span>
<span class="line"><span>     2  istore_1 [i]</span></span>
<span class="line"><span>     3  goto 9</span></span>
<span class="line"><span>     6  iinc 1 -1 [i] // i--</span></span>
<span class="line"><span>     9  iload_1 [i]</span></span>
<span class="line"><span>    10  ifge 6</span></span>
<span class="line"><span>    13  return</span></span></code></pre></div><h2 id="综合示例" tabindex="-1">综合示例 <a class="header-anchor" href="#综合示例" aria-label="Permalink to &quot;综合示例&quot;">​</a></h2><p>下面我们来看一个综合的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public static int bar(int i) {</span></span>
<span class="line"><span>  return ((i + 1) - 2) * 3 / 4;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 对应的字节码如下：</span></span>
<span class="line"><span>Code:</span></span>
<span class="line"><span>  stack=2, locals=1, args_size=1</span></span>
<span class="line"><span>     0: iload_0</span></span>
<span class="line"><span>     1: iconst_1</span></span>
<span class="line"><span>     2: iadd</span></span>
<span class="line"><span>     3: iconst_2</span></span>
<span class="line"><span>     4: isub</span></span>
<span class="line"><span>     5: iconst_3</span></span>
<span class="line"><span>     6: imul</span></span>
<span class="line"><span>     7: iconst_4</span></span>
<span class="line"><span>     8: idiv</span></span>
<span class="line"><span>     9: ireturn</span></span></code></pre></div><p>这里我定义了一个bar方法。它将接收一个int类型的参数，进行一系列计算之后再返回。</p><p>对应的字节码中的stack=2, locals=1代表该方法需要的操作数栈空间为2，局部变量数组空间为1。当调用bar(5)时，每条指令执行前后局部变量数组空间以及操作数栈的分布如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/c57cb9c2222f0f79459bf4c58e1a4c32.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/c57cb9c2222f0f79459bf4c58e1a4c32.png" alt=""></a></p><h2 id="java字节码简介" tabindex="-1">Java字节码简介 <a class="header-anchor" href="#java字节码简介" aria-label="Permalink to &quot;Java字节码简介&quot;">​</a></h2><p>前面我已经介绍了加载常量指令、操作数栈专用指令以及局部变量区访问指令。下面我们来看看其他的类别。</p><p>Java相关指令，包括各类具备高层语义的字节码，即new（后跟目标类，生成该类的未初始化的对象），instanceof（后跟目标类，判断栈顶元素是否为目标类/接口的实例。是则压入1，否则压入0），checkcast（后跟目标类，判断栈顶元素是否为目标类/接口的实例。如果不是便抛出异常），athrow（将栈顶异常抛出），以及monitorenter（为栈顶对象加锁）和monitorexit（为栈顶对象解锁）。</p><p>此外，该类型的指令还包括字段访问指令，即静态字段访问指令getstatic、putstatic，和实例字段访问指令getfield、putfield。这四条指令均附带用以定位目标字段的信息，但所消耗的操作数栈元素皆不同。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/da3ff3aa4aaa2531d23286fec65b08d9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/da3ff3aa4aaa2531d23286fec65b08d9.png" alt=""></a></p><p>以putfield为例，在上图中，它会把值v存储至对象obj的目标字段之中。</p><p>方法调用指令，包括invokestatic，invokespecial，invokevirtual，invokeinterface以及invokedynamic。这几条字节码我们已经反反复复提及了，就不再具体介绍各自的含义了。</p><p>除invokedynamic外，其他的方法调用指令所消耗的操作数栈元素是根据调用类型以及目标方法描述符来确定的。在进行方法调用之前，程序需要依次压入调用者（invokestatic不需要），以及各个参数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  public int neg(int i) {</span></span>
<span class="line"><span>    return -i;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  public int foo(int i) {</span></span>
<span class="line"><span>    return neg(neg(i));</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // foo方法对应的字节码如下：foo方法对应的字节码如下：</span></span>
<span class="line"><span>  public int foo(int i);</span></span>
<span class="line"><span>    0  aload_0 [this]</span></span>
<span class="line"><span>    1  aload_0 [this]</span></span>
<span class="line"><span>    2  iload_1 [i]</span></span>
<span class="line"><span>    3  invokevirtual FooTest.neg(int) : int [25]</span></span>
<span class="line"><span>    6  invokevirtual FooTest.neg(int) : int [25]</span></span>
<span class="line"><span>    9  ireturn</span></span></code></pre></div><p>以上面这段代码为例，当调用foo(2)时，每条指令执行前后局部变量数组空间以及操作数栈的分布如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/476fa1bcb6b36b5b651c2a4101073295.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/476fa1bcb6b36b5b651c2a4101073295.png" alt=""></a></p><p>数组相关指令，包括新建基本类型数组的newarray，新建引用类型数组的anewarray，生成多维数组的multianewarray，以及求数组长度的arraylength。另外，它还包括数组的加载指令以及存储指令。这些指令是区分类型的。例如，int数组的加载指令为iaload，存储指令为iastore。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/8ee0ed86242a63b566d55297a88da9f1.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/8ee0ed86242a63b566d55297a88da9f1.jpg" alt=""></a></p><p><strong>数组访问指令表</strong></p><p>控制流指令，包括无条件跳转goto，条件跳转指令，tableswitch和lookupswtich（前者针对密集的cases，后者针对稀疏的cases），返回指令，以及被废弃的jsr，ret指令。其中返回指令是区分类型的。例如，返回int值的指令为ireturn。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/f5195b5425a9547af9ce8371aef5c4f0.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Java%E8%99%9A%E6%8B%9F%E6%9C%BA/images/14794/f5195b5425a9547af9ce8371aef5c4f0.jpg" alt=""></a></p><p><strong>返回指令表</strong></p><p>除返回指令外，其他的控制流指令均附带一个或者多个字节码偏移量，代表需要跳转到的位置。例如下面的abs方法中偏移量为1的条件跳转指令，当栈顶元素小于0时，跳转至偏移量为6的字节码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  public int abs(int i) {</span></span>
<span class="line"><span>    if (i &gt;= 0) {</span></span>
<span class="line"><span>      return i;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return -i;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // 对应的字节码如下所示：</span></span>
<span class="line"><span>  public int abs(int i);</span></span>
<span class="line"><span>    0  iload_1 [i]</span></span>
<span class="line"><span>    1  iflt 6</span></span>
<span class="line"><span>    4  iload_1 [i]</span></span>
<span class="line"><span>    5  ireturn</span></span>
<span class="line"><span>    6  iload_1 [i]</span></span>
<span class="line"><span>    7  ineg</span></span>
<span class="line"><span>    8  ireturn</span></span></code></pre></div><p>剩余的Java字节码几乎都和计算相关，这里就不再详细阐述了。</p><h2 id="总结与实践" tabindex="-1">总结与实践 <a class="header-anchor" href="#总结与实践" aria-label="Permalink to &quot;总结与实践&quot;">​</a></h2><p>今天我简单介绍了各种类型的Java字节码。</p><p>Java方法的栈桢分为操作数栈和局部变量区。通常来说，程序需要将变量从局部变量区加载至操作数栈中，进行一番运算之后再存储回局部变量区中。</p><p>Java字节码可以划分为很多种类型，如加载常量指令，操作数栈专用指令，局部变量区访问指令，Java相关指令，方法调用指令，数组相关指令，控制流指令，以及计算相关指令。</p><p>今天的实践环节，你可以尝试自己分析一段较为复杂的字节码，在草稿上画出局部变量数组以及操作数栈分布图。当碰到不熟悉的指令时，你可以查阅 <a href="https://docs.oracle.com/javase/specs/jvms/se10/html/jvms-6.html#jvms-6.5" target="_blank" rel="noreferrer">Java虚拟机规范第6.5小节</a> ，或者 <a href="https://cs.au.dk/~mis/dOvs/jvmspec/ref-Java.html" target="_blank" rel="noreferrer">此链接</a>。</p>`,72)])])}const d=s(i,[["render",t]]);export{b as __pageData,d as default};
